// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract MessageBoard {
    struct Message {
        address author;
        string content;
        uint256 timestamp;
    }

    Message public lastMessage;
    uint256 public messageCount;

    event NewMessage(address indexed author, string content, uint256 timestamp);
    event TipSent(address indexed tipper, address indexed recipient, uint256 amount);

    function postMessage(string memory _content) public payable {
        // If there's a previous message author, send them the tip
        if (lastMessage.author != address(0) && msg.value > 0) {
            payable(lastMessage.author).transfer(msg.value);
            emit TipSent(msg.sender, lastMessage.author, msg.value);
        }

        lastMessage = Message(msg.sender, _content, block.timestamp);
        messageCount++;

        emit NewMessage(msg.sender, _content, block.timestamp);
    }

    function getLastMessage() public view returns (
        address author,
        string memory content,
        uint256 timestamp
    ) {
        return (lastMessage.author, lastMessage.content, lastMessage.timestamp);
    }
}
